        "ipdSharingStatementModule": {
          "ipdSharing": "UNDECIDED",
          "description": "Novartis is committed to sharing with qualified external researchers, access to patient-level data and supporting clinical documents from eligible studies. These requests are reviewed and approved by an independent review panel on the basis of scientific merit. All data provided is anonymized to respect the privacy of patients who have participated in the trial in line with applicable laws and regulations.\n\nThis trial data availability is according to the criteria and process described on www.clinicalstudydatarequest.com"
        }
      },
      "resultsSection": {
        "participantFlowModule": {
          "preAssignmentDetails": "This was a 2-Period study in which participants were randomized to one of three treatment groups (i.e., \"secukinumab 300mg s.c. injection\", \"secukinumab 1500mg s.c. injection\" and \"placebo s.c. injection\") in Period 1 and then some participants switched to Arms/Groups \"Group 4\", \"Group 5\", and \"Group 6\", in Period 2.",
          "recruitmentDetails": "Of 349 patients screened for the study, 271 passed screening and 258 were randomized (103 to secukinumab 300 mg, 103 to secukinumab 150 mg, and 52 to placebo). A higher percentage of patients in the secukinumab 300 mg group completed Period 1 (94.2%) than in the secukinumab 150 mg (90.3%) or placebo (88.5%) groups.",
          "groups": [
            {
              "id": "FG000",
              "title": "Group 1",
              "description": "secukinumab 300mg s.c. injection"
            },
            {
              "id": "FG001",
              "title": "Group 2",
              "description": "secukinumab 150 mg s.c. injection"
            },
            {
              "id": "FG002",
              "title": "Group 3",
              "description": "Placebo s.c. injection"
            },
            {
              "id": "FG003",
              "title": "Group 4",
              "description": "Secukinumab 150 mg - 150 mg (R)"
            },
            {
              "id": "FG004",
              "title": "Group 5",
              "description": "Secukinumab 150 mg - 300 mg (NR)"
            },
            {
              "id": "FG005",
              "title": "Group 6",
              "description": "Placebo - Secukinumab 300 mg"
            }
          ],
          "periods": [
            {
              "title": "Period 1",
              "milestones": [
                {
                  "type": "STARTED",
                  "comment": "Screened patients=349 Screen passed patient=271 Screened failure=78 Randomized=103",
                  "achievements": [
                    {
                      "groupId": "FG000",
                      "numSubjects": "103"
                    },
                    {
                      "groupId": "FG001",
                      "numSubjects": "103"
