        "outcomeMeasuresModule": {
          "outcomeMeasures": [
            {
              "type": "PRIMARY",
              "title": "Percent of Patients Achieving American College of Rheumatology Score of at Least 20% (ACR20) Response Criteria on Secukinumab 300 mg and 150 mg vs. Placebo at Week 16",
              "description": "A patient was considered as improved according to the ACR20 criteria if she/he had at least 20% improvement in two of the following measures:Tender joint count, Swollen joint count and at least 3 of the following 5 measures: Patient's assessment of pain, Patient's global assessment disease activity, Physician's global assessment of disease activity, Health Assessment Questionnaire (HAQ©) score,Acute phase reactant (hsCRP or ESR).\n\nOdds ratio, 95% confidence interval for odds ratio, and p-value are from a logistic regression model with treatment (3 treatment groups), methotrexate usage at baseline (yes, no) and body weight (kg) as explanatory variables.",
              "populationDescription": "The Full Analysis Set (FAS) includes all patients assigned study medication. Patients inappropriately randomized (e.g., IRT was called in error for randomization of a screen failed patient) were excluded from analysis set. Following the intent-to-treat principle, patients were analyzed according to the treatment they were assigned at randomization.",
              "reportingStatus": "POSTED",
              "paramType": "NUMBER",
              "unitOfMeasure": "percentage of participants",
              "timeFrame": "16 Weeks",
              "groups": [
