          },
          "briefTitle": "Effects of the Integrated-based Laughing Qigong Program on Resilience in Community-dwelling Older Adults",
          "officialTitle": "Effects of the Integrated-based Laughing Qigong Program on Resilience in Community-dwelling Older Adults: An Explanatory Sequential Mixed Method"
        },
        "statusModule": {
