          },
          "briefTitle": "Superior Glenohumeral Translation in Patients With Degenerative Rotator Cuff Tears",
          "officialTitle": "ROTCUFF - Measuring Load-induced Superior Glenohumeral Translation in Patients With Degenerative Rotator Cuff Tears and Asymptomatic Subjects: 3-dimensional Motion Analysis Versus Single Plane Fluoroscopy",
          "acronym": "ROTCUFF"
        },
        "statusModule": {
          "statusVerifiedDate": "2022-03",
          "overallStatus": "COMPLETED",
