              "timeFrame": "Baseline"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Disabilities of arm, shoulder and Hand (DASH)",
              "description": "assessed using the Quick DASH (0 - no problems, 100 - extreme problems)",
              "timeFrame": "Baseline"
            },
            {
              "measure": "Shoulder function",
              "description": "assessed using the Constant Shoulder Score (0 - no problems, \\>30 extreme problems)",
              "timeFrame": "Baseline"
            },
            {
              "measure": "Shoulder pain",
              "description": "assessed using a 15 cm visual analogue scale converted to 0 to 100 scale (0 - no pain; 100 - worst pain imaginable)",
              "timeFrame": "Baseline"
            },
            {
              "measure": "Critical shoulder angle (CSA)",
              "description": "measured on frontal plane radiographs in neutral arm position available from the clinical consultation. The CSA is the angle between the line connecting the superior with the inferior border of the glenoid fossa and the line connecting the inferior border of the glenoid fossa with the most inferolateral point of the acromion",
              "timeFrame": "Baseline"
            },
            {
              "measure": "Muscle activity",
              "description": "root mean square of the electromyography (EMG) signal during the arm movements calculated and normalised to the maximal obtained signal intensity",
              "timeFrame": "Baseline"
            },
            {
              "measure": "Glenohumeral translation from fluoroscopy",
              "description": "the perpendicular distance of the centre of the glenohumeral joint and the x-axis of the scapula coordinate system will be measured. Glenohumeral translation will be defined as the difference in this distance between the abducted arm positions and the resting arm position",
              "timeFrame": "Baseline"
            }
          ]
