          "briefTitle": "Efficacy of GBT vs SRP+US, in the Treatment of Severe Generalized Periodontitis.",
          "officialTitle": "Efficacy of Combined Air-abrasive+Ultrasonic (Guided Biofilm Therapy GBT) vs. Standard Root Debridement (Scaling and Root Planing+ Ultrasonic SRP+US) in the Treatment of Severe Generalized Periodontitis: A Randomized Clinical Trial",
          "acronym": "ERISRP"
        },
        "statusModule": {
          "statusVerifiedDate": "2021-11",
          "overallStatus": "COMPLETED",
          "expandedAccessInfo": {
            "hasExpandedAccess": false
          },
          "startDateStruct": {
