          }
        },
        "sponsorCollaboratorsModule": {
          "responsibleParty": {
            "type": "PRINCIPAL_INVESTIGATOR",
            "investigatorFullName": "Magda Mensi",
            "investigatorTitle": "Principal Investigator",
            "investigatorAffiliation": "Azienda Socio Sanitaria Territoriale degli Spedali Civili di Brescia"
          },
          "leadSponsor": {
            "name": "Azienda Socio Sanitaria Territoriale degli Spedali Civili di Brescia",
