            "primaryPurpose": "TREATMENT",
            "maskingInfo": {
              "masking": "NONE"
            }
          },
          "enrollmentInfo": {
            "count": 20,
            "type": "ESTIMATED"
          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "1",
              "type": "EXPERIMENTAL",
              "description": "Islet cell transplant",
              "interventionNames": [
                "Procedure: Pancreatic Islets of Langerhans Cell Transplant"
              ]
            }
          ],
          "interventions": [
            {
              "type": "PROCEDURE",
              "name": "Pancreatic Islets of Langerhans Cell Transplant",
              "description": "Transplantation of islet cells will be given to eligible patients, up to three times during the study, using cell quantities based on body weight.",
              "armGroupLabels": [
                "1"
              ],
              "otherNames": [
                "Islet Cell Transplant",
                "Pancreatic Islet Cell Transplantation"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "A decrease in the average daily insulin requirement post-islet cell transplantation.",
              "timeFrame": "Post-transplant"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Type I Diabetes Mellitus for at least 5 years\n* Unstable control of diabetes despite intensive care by an endocrinologist, including episodes of dangerously low blood sugars\n* Group I must have healthy kidneys\n* Group II (islet after kidney) must have a stable kidney allograft for at least 6 months\n\nExclusion Criteria:\n\n* Unstable diabetic eye disease\n* Poor kidney function\n* Type II Diabetes as determined by blood tests\n* Any history of cancer, except certain skin cancers\n* Pregnant or unwilling to use adequate birth control\n* Very high hemoglobin A1c levels\n* Poor control of blood pressure, despite use of medications\n* Very high insulin requirements\n* History of exposure to HIV\n* Active Hepatitis B or Hepatitis C infection",
          "healthyVolunteers": false,
          "sex": "ALL",
          "minimumAge": "18 Years",
          "maximumAge": "65 Years",
          "stdAges": [
            "ADULT",
            "OLDER_ADULT"
          ]
        },
