          }
        },
        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Information brochure",
              "type": "EXPERIMENTAL",
              "description": "Intervention: The parents are given a specific information brochure that describes the procedures that the child is going through during anesthesia when it has been decided that the child is going to have the surgery.",
              "interventionNames": [
                "Behavioral: Specific information brochure"
              ]
            },
            {
              "label": "Information as usual",
              "type": "NO_INTERVENTION",
              "description": "Information as usual, i.e. oral information about the procedures to parents when they arrive at the hospital with the child that is going to have the surgery."
            }
          ],
          "interventions": [
            {
              "type": "BEHAVIORAL",
              "name": "Specific information brochure",
              "description": "A purpose-designed brochure about anesthesia and surgery in the ear in children is developed by the investigators. This brochure has photos and describes the procedures the child is going through.",
              "armGroupLabels": [
                "Information brochure"
              ]
            }
          ]
        },
        "outcomesModule": {
          "primaryOutcomes": [
            {
              "measure": "Satisfaction with information",
              "description": "Self-reported satisfaction with provided information on a 5 point Likert scale where 1 is less satisfied and 5 is high satisfaction (range 1-5). In total four questions (sum score range 4-20)",
              "timeFrame": "10 minutes"
            },
            {
              "measure": "Preparedness for the operating room setting",
              "description": "Self-reported to what degree parents feel prepared as to what will happen before/during induction of anaesthesia on a 5 point Likert scale where 1 is less prepared and 5 is very well prepared (range 1-5). In total two questions (sum score range 2-10)",
              "timeFrame": "10 minutes"
            }
          ],
          "secondaryOutcomes": [
            {
              "measure": "Perceived Stress Score (PSS-14)",
              "description": "Self-reported perceived stress measured by 14 questions on a 5-point Likert scale where 1 is Never and 5 is very often. Range for the total score is 1-70.",
              "timeFrame": "10 minutes"
            }
          ]
        },
        "eligibilityModule": {
          "eligibilityCriteria": "Inclusion Criteria:\n\n* Parents with children undergoing ear-nose-throat surgery in the study period\n\nExclusion Criteria:\n\n* Parents who do not speak nor read Norwegian.\n* Parents who do not want to participate",
