        "armsInterventionsModule": {
          "armGroups": [
            {
              "label": "Caffeine Based Cream",
              "type": "EXPERIMENTAL",
              "description": "caffeine based cream during and for 4 weeks following radiation",
              "interventionNames": [
                "Drug: Caffeine anhydrous 5% added to Lipoderm Cream Base."
              ]
            },
            {
