          ],
          "interventions": [
            {
              "type": "DRUG",
              "name": "Caffeine anhydrous 5% added to Lipoderm Cream Base.",
              "description": "Caffeine USP Anhydrous 5 gm Ethoxy Digylco Reagent 10 ml Professional Compounding Centers of America (PCCA) Lipoderm Base 85 gm",
              "armGroupLabels": [
